<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/purchase_step14.php';if(empty($_SESSION['pb_csrf']))$_SESSION['pb_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['pb_csrf'];$error=null;$success=null;$suppliers=[];$products=[];$pos=[];$bills=[];$selected=(int)($_GET['bill']??$_POST['purchase_bill_id']??0);$items=[];$state=null;
try{$pdo=business_db();purchase_step14_ensure($pdo);$ctx=purchase_step14_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'');if($action==='create'){$selected=purchase_step14_create_bill($pdo,(int)$_POST['supplier_id'],(int)($_POST['purchase_order_id']??0)?:null,(string)$_POST['invoice_number'],(string)$_POST['invoice_date'],$_POST['due_date']??null,(float)($_POST['other_charges']??0),(string)($_POST['notes']??''));$success='Purchase Bill created.';}elseif($action==='add_item'){purchase_step14_add_bill_item($pdo,$selected,(int)$_POST['product_id'],(float)$_POST['quantity'],(float)$_POST['unit_cost'],(float)($_POST['line_discount']??0),(float)($_POST['tax_amount']??0),null,(string)($_POST['notes']??''));$success='Bill item added.';}elseif($action==='cancel'){purchase_step14_cancel_bill($pdo,$selected,(string)($_POST['reason']??''));$success='Bill cancelled safely.';}}$suppliers=purchase_step14_suppliers($pdo,$orgId,true);$products=product_step11_catalog_rows($pdo,$orgId,'','ALL');$pos=purchase_step14_po_rows($pdo,$orgId);foreach(purchase_step14_bill_rows($pdo,$orgId,'all') as $b){purchase_step14_recalc_bill($pdo,$orgId,(int)$b['id']);}$bills=purchase_step14_bill_rows($pdo,$orgId,'all');if($selected>0){$state=purchase_step14_recalc_bill($pdo,$orgId,$selected);$stmt=$pdo->prepare("SELECT i.*,p.sku,p.product_name FROM purchase_bill_items i JOIN products p ON p.id=i.product_id WHERE i.organization_id=? AND i.purchase_bill_id=? ORDER BY i.id");$stmt->execute([$orgId,$selected]);$items=$stmt->fetchAll();}}catch(Throwable $e){$error=$e->getMessage();}
function pb_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function pb_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Purchase Bills - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="purchase_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 14 • Supplier Bills / Invoices</small></span></a><div class="os-top-actions"><a class="os-btn" href="purchase_orders.php">POs</a><a class="os-btn" href="purchase_receipts.php">Receipts</a><a class="os-btn primary" href="supplier_payments.php">Payables</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Purchases</div><nav class="os-nav"><a href="purchase_center.php"><i class="dot"></i>Purchase Center</a><a href="supplier_center.php"><i class="dot"></i>Suppliers</a><a href="purchase_orders.php"><i class="dot"></i>Purchase Orders</a><a class="active" href="purchase_bills.php"><i class="dot"></i>Bills / Invoices</a><a href="purchase_receipts.php"><i class="dot"></i>Receipts</a><a href="supplier_payments.php"><i class="dot"></i>Payables</a><a href="purchase_returns.php"><i class="dot"></i>Returns</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 14C • SUPPLIER BILLS</div><h1>Record the real supplier invoice before money or stock moves.</h1><p>Bill total is reconciled from product lines: quantity × actual unit cost − discount + tax + other charges. Receipt and payment remain separate workflows.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'BILL CENTER LIVE':'Review required' ?></span><span class="os-chip"><?= count($bills) ?> bills</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Bill diagnostic:</strong> <?= pb_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Saved:</strong> <?= pb_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-4"><h2>Create Supplier Bill</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= pb_h($csrf) ?>"><input type="hidden" name="action" value="create"><label>Supplier<select name="supplier_id" required><option value="">Choose supplier…</option><?php foreach($suppliers as $s):?><option value="<?= (int)$s['id'] ?>"><?= pb_h($s['supplier_name'].' • '.$s['supplier_code']) ?></option><?php endforeach;?></select></label><label>Related PO (optional)<select name="purchase_order_id"><option value="">None / direct bill</option><?php foreach($pos as $o):if($o['status']==='cancelled')continue;?><option value="<?= (int)$o['id'] ?>"><?= pb_h($o['po_number'].' • '.$o['supplier_name']) ?></option><?php endforeach;?></select></label><label>Invoice Number<input name="invoice_number" required></label><label>Invoice Date<input type="date" name="invoice_date" value="<?= date('Y-m-d') ?>" required></label><label>Due Date<input type="date" name="due_date"><small>Blank = supplier payment terms.</small></label><label>Other Charges<input type="number" min="0" step="0.01" name="other_charges" value="0"></label><label>Notes<textarea name="notes" rows="2"></textarea></label><button>Create Bill →</button></form><?php if($selected):?><hr><h2>Add Bill Item</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= pb_h($csrf) ?>"><input type="hidden" name="action" value="add_item"><input type="hidden" name="purchase_bill_id" value="<?= $selected ?>"><label>Product<select name="product_id" required><option value="">Choose product…</option><?php foreach($products as $p):?><option value="<?= (int)$p['id'] ?>"><?= pb_h(($p['sku']?:'—').' • '.$p['product_name']) ?></option><?php endforeach;?></select></label><label>Billed Quantity<input type="number" min="0.001" step="0.001" name="quantity" required></label><label>Actual Unit Cost<input type="number" min="0" step="0.01" name="unit_cost" required></label><label>Line Discount<input type="number" min="0" step="0.01" name="line_discount" value="0"></label><label>Tax Amount<input type="number" min="0" step="0.01" name="tax_amount" value="0"></label><label>Notes<input name="notes"></label><button>Add Bill Item →</button></form><?php if($state&&$state['items']===0):?><form method="post" class="pp-form" style="margin-top:12px"><input type="hidden" name="csrf" value="<?= pb_h($csrf) ?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="purchase_bill_id" value="<?= $selected ?>"><label>Cancel Reason<input name="reason" minlength="5" required></label><button>Cancel Empty Bill</button></form><?php endif;?><?php endif;?></article><article class="os-card pp-span-8"><h2>Supplier Bills</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Invoice</th><th>Supplier</th><th>Date / Due</th><th>Total</th><th>Return</th><th>Paid</th><th>Outstanding</th><th>Receipt</th><th>Payment</th></tr></thead><tbody><?php foreach($bills as $b):?><tr><td><a href="?bill=<?= (int)$b['id'] ?>"><b><?= pb_h($b['invoice_number']) ?></b></a><small><?= pb_h($b['po_number']?:'Direct bill') ?></small></td><td><?= pb_h($b['supplier_name']) ?></td><td><?= pb_h($b['invoice_date']) ?><small>Due <?= pb_h($b['due_date']?:'—') ?></small></td><td><?= pb_m($b['total_amount']) ?></td><td><?= pb_m($b['return_credit']) ?></td><td><?= pb_m($b['paid_amount']) ?></td><td><b><?= pb_m($b['outstanding']) ?></b></td><td><span class="pp-badge"><?= pb_h(strtoupper($b['receipt_status'])) ?></span></td><td><span class="pp-badge <?= $b['payment_status']==='credit'?'warn':'' ?>"><?= pb_h(strtoupper($b['payment_status'])) ?></span></td></tr><?php endforeach;?><?php if(!$bills):?><tr><td colspan="9">No supplier bills yet.</td></tr><?php endif;?></tbody></table></div><?php if($selected&&$state):?><div class="pp-summary" style="margin-top:16px"><div><small>Subtotal</small><b><?= pb_m($state['subtotal']) ?></b></div><div><small>Discount</small><b><?= pb_m($state['discount']) ?></b></div><div><small>Tax</small><b><?= pb_m($state['tax']) ?></b></div><div><small>Total</small><b><?= pb_m($state['total']) ?></b></div><div><small>Outstanding</small><b><?= pb_m($state['outstanding']) ?></b></div></div><h2 style="margin-top:16px">Selected Bill Items</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Product</th><th>Billed</th><th>Received</th><th>Unit Cost</th><th>Discount</th><th>Tax</th><th>Line Total</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><b><?= pb_h($i['sku']) ?></b><small><?= pb_h($i['product_name']) ?></small></td><td><?= pb_h($i['billed_quantity']) ?></td><td><?= pb_h($i['received_quantity']) ?></td><td><?= pb_m($i['unit_cost']) ?></td><td><?= pb_m($i['line_discount']) ?></td><td><?= pb_m($i['tax_amount']) ?></td><td><?= pb_m($i['line_total']) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></article></section><?php endif;?><div class="os-footer-note"><strong>Bill rule:</strong> Bill creates supplier liability only. No inventory quantity changes until Receipt is posted.</div></main></div></body></html>